inputs.script:
$ErrorActionPreference = 'Stop'

$downloadRoot = [IO.Path]::GetFullPath("$(System.DefaultWorkingDirectory)")
$releaseId = "$(Release.ReleaseId)"
if ([string]::IsNullOrWhiteSpace($releaseId) -or $releaseId -like '$(*') { $releaseId = [guid]::NewGuid().ToString('N') }
$stageKey = "$(StageKey)"
$stageRoot = Join-Path "$(Agent.TempDirectory)" ("FFTestAutomation\{0}\{1}" -f $releaseId, $stageKey)
$packageRoot = Join-Path $stageRoot 'package'

if (Test-Path -LiteralPath $stageRoot) { Remove-Item -LiteralPath $stageRoot -Recurse -Force }
New-Item -ItemType Directory -Path $packageRoot -Force | Out-Null

$runReadyZip = Get-ChildItem -LiteralPath $downloadRoot -Recurse -File -Filter "$(RunReadyZipName)" -ErrorAction SilentlyContinue |
    Sort-Object LastWriteTimeUtc -Descending |
    Select-Object -First 1

if ($runReadyZip) {
    Write-Host "Using CI run-ready package: $($runReadyZip.FullName)"
    Expand-Archive -LiteralPath $runReadyZip.FullName -DestinationPath $packageRoot -Force
}
else {
    $settingsFile = Get-ChildItem -LiteralPath $downloadRoot -Recurse -File -Filter 'Tosca.runsettings' -ErrorAction SilentlyContinue |
        Where-Object {
            (Test-Path -LiteralPath (Join-Path $_.Directory.FullName 'tests')) -and
            (Test-Path -LiteralPath (Join-Path $_.Directory.FullName 'scripts\Initialize-PipelineTestOutput.ps1'))
        } |
        Select-Object -First 1

    if (-not $settingsFile) {
        throw "The linked CI artifact does not contain $(RunReadyZipName) or an extracted executable testpackage. Reconnect the Build artifact after importing this release definition."
    }

    $sourceRoot = $settingsFile.Directory.FullName
    Write-Host "Using extracted CI artifact folder: $sourceRoot"
    Copy-Item -Path (Join-Path $sourceRoot '*') -Destination $packageRoot -Recurse -Force
}

$requiredFiles = @(
    'Tosca.runsettings',
    'config\framework.json',
    'scripts\Initialize-PipelineTestOutput.ps1',
    'scripts\Generate-ConsolidatedReport.ps1',
    'tools\generate_consolidated_report.py',
    'tests\CommercialLines.DuckCreek.Tests\bin\Release\net8.0\CommercialLines.DuckCreek.Tests.dll',
    'tests\CommercialLines.ExpertQuote.Tests\bin\Release\net8.0\CommercialLines.ExpertQuote.Tests.dll',
    'tests\PersonalLines.DuckCreek.Tests\bin\Release\net8.0\PersonalLines.DuckCreek.Tests.dll'
)
foreach ($relativePath in $requiredFiles) {
    $fullPath = Join-Path $packageRoot $relativePath
    if (-not (Test-Path -LiteralPath $fullPath -PathType Leaf)) { throw "Required CI artifact file is missing: $relativePath" }
}

$headless = $true
if (-not [bool]::TryParse("$(Headless)", [ref]$headless)) { throw "Headless must be true or false; received '$(Headless)'." }
$configFiles = Get-ChildItem -LiteralPath $packageRoot -Recurse -File -Filter 'framework.json' |
    Where-Object { $_.FullName -match '[\\/]config[\\/]framework\.json$' }
if (-not $configFiles) { throw 'No framework.json files were found in the CI artifact.' }
foreach ($configFile in $configFiles) {
    $config = Get-Content -LiteralPath $configFile.FullName -Raw | ConvertFrom-Json
    if ($null -eq $config.browser) { throw "browser configuration is missing from $($configFile.FullName)" }
    $config.browser.headless = $headless
    $config | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $configFile.FullName -Encoding UTF8
}

$playwrightScript = Get-ChildItem -LiteralPath $packageRoot -Recurse -File -Filter 'playwright.ps1' |
    Where-Object { Test-Path -LiteralPath (Join-Path $_.Directory.FullName 'Microsoft.Playwright.dll') } |
    Select-Object -First 1
if (-not $playwrightScript) { throw 'No playable playwright.ps1 and Microsoft.Playwright.dll pair exists in the CI artifact.' }
& $playwrightScript.FullName install "$(PlaywrightBrowser)"
if ($LASTEXITCODE -ne 0) { throw "Playwright $(PlaywrightBrowser) installation failed with exit code $LASTEXITCODE." }

$frameworkConfig = [IO.Path]::GetFullPath((Join-Path $packageRoot 'config\framework.json'))
$env:TEST_FRAMEWORK_CONFIG = $frameworkConfig
Write-Host "##vso[task.setvariable variable=TEST_PACKAGE_ROOT]$packageRoot"
Write-Host "##vso[task.setvariable variable=TEST_FRAMEWORK_CONFIG]$frameworkConfig"

$initializer = Join-Path $packageRoot 'scripts\Initialize-PipelineTestOutput.ps1'
& $initializer -ArtifactRoot $packageRoot -ResultsDirectory "$(StageResultsDirectory)"

Write-Host "Prepared test package: $packageRoot"
Write-Host "Stage result scope: $(StageResultsDirectory)"
$global:LASTEXITCODE = 0

$ErrorActionPreference = 'Continue'

$packageRoot = "$(TEST_PACKAGE_ROOT)"
$resultsDirectory = "$(StageResultsDirectory)"
if ([string]::IsNullOrWhiteSpace($packageRoot) -or -not (Test-Path -LiteralPath $packageRoot -PathType Container)) {
    Write-Warning 'The prepared test package is unavailable, so consolidated reporting is skipped.'
    exit 0
}

$evidenceRoot = Join-Path (Join-Path $packageRoot $resultsDirectory) 'Artifacts'
$scenarioResult = $null
if (Test-Path -LiteralPath $evidenceRoot -PathType Container) {
    $scenarioResult = Get-ChildItem -LiteralPath $evidenceRoot -Recurse -File -Filter 'scenario-result.json' -ErrorAction SilentlyContinue | Select-Object -First 1
}
if (-not $scenarioResult) {
    Write-Warning "No scenario-result.json was produced under $evidenceRoot. VSTest/TRX results remain available in Azure Test Runs."
    exit 0
}

$reportScript = Join-Path $packageRoot 'scripts\Generate-ConsolidatedReport.ps1'
try {
    & $reportScript -ResultsDirectory $resultsDirectory
    if ($LASTEXITCODE -ne 0) { throw "Report generator exited with code $LASTEXITCODE." }
}
catch {
    Write-Warning "Consolidated report generation failed: $($_.Exception.Message)"
    exit 0
}

$reportRoot = Join-Path (Join-Path $packageRoot $resultsDirectory) 'ConsolidatedReport'
$reportHtml = Join-Path $reportRoot 'report.html'
$logHtml = Join-Path $reportRoot 'log.html'
$summaryJson = Join-Path $reportRoot 'summary.json'

if (Test-Path -LiteralPath $reportHtml -PathType Leaf) {
    Write-Host "##vso[task.uploadsummary]$reportHtml"
    Write-Host "##vso[task.uploadfile]$reportHtml"
}
foreach ($file in @($logHtml, $summaryJson)) {
    if (Test-Path -LiteralPath $file -PathType Leaf) { Write-Host "##vso[task.uploadfile]$file" }
}
Write-Host "Consolidated report: $reportHtml"
exit 0

